import{_ as o,C as n,c as r,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Manage sales teams","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/pipeline/manage-sales-teams.md","filePath":"master/sales/crm/pipeline/manage-sales-teams.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/pipeline/manage-sales-teams.md"};function d(h,e,m,g,c,p){const a=n("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="manage-sales-teams" tabindex="-1">Manage sales teams <a class="header-anchor" href="#manage-sales-teams" aria-label="Permalink to &quot;Manage sales teams&quot;">​</a></h1><p>A sales team groups salespeople who work on the same deals. Each team has a leader, members and a monthly invoicing target. The Teams page shows how each team is doing, and the team form sets it up.</p><blockquote><p><strong>In simple words:</strong> A team is a group of salespeople with one goal. You see the goal and the progress on one card.</p></blockquote><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Some parts of the team form depend on <code>CRM → Settings → Manage CRM</code>.</p><ul><li><strong>Salespeople in Multiple Teams:</strong> when off, a salesperson belongs to one team only. Adding them to a second team asks you to confirm the move.</li><li><strong>Automatic Lead Assignment:</strong> turns on the <strong>Assignment Rules</strong> tab, capacity fields and the <strong>Assign Leads</strong> button.</li></ul><p>See <a href="./../configuration/settings.html">CRM settings</a>.</p><h2 id="the-teams-page" tabindex="-1">The Teams page <a class="header-anchor" href="#the-teams-page" aria-label="Permalink to &quot;The Teams page&quot;">​</a></h2><p>Open <code>CRM → Sales → Teams</code>. It has two layouts: <strong>Grid</strong> and <strong>List</strong>. Grid is the default. The header button <strong>New Sales Team</strong> opens the team form.</p>',9)),s(a,{src:"/images1/crm/sales-teams-cards.png",alt:"Sales Teams page with team cards and the New Sales Team button"}),e[1]||(e[1]=t('<h3 id="grid-cards" tabindex="-1">Grid cards <a class="header-anchor" href="#grid-cards" aria-label="Permalink to &quot;Grid cards&quot;">​</a></h3><p>Each team is a card. In the dev data the cards are <strong>Sales</strong>, <strong>Website</strong>, <strong>Point of Sale</strong> and <strong>Pre-Sales</strong>.</p><table tabindex="0"><thead><tr><th>Line on the card</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Team name</strong></td><td>Click it to open the team pipeline.</td></tr><tr><td><strong>Open Opportunities</strong></td><td>How many deals of the team are not won or lost. The amount beside it is their <strong>Expected Revenue</strong>. Click the count to see them.</td></tr><tr><td><strong>Quotations</strong></td><td>Draft and sent quotations of the team, with their untaxed total. Shown only when there are some.</td></tr><tr><td><strong>Order to Invoice</strong></td><td>Confirmed orders waiting to be invoiced, with their untaxed total. Shown only when there are some.</td></tr><tr><td><strong>Invoiced This Month</strong></td><td>Posted invoices of the team since the start of this month, shown as <code>invoiced of target</code>. Shown only when the team has a target.</td></tr><tr><td><strong>Bar chart</strong></td><td>New opportunities per week, for the last five weeks. A grey chart marked <strong>Sample data</strong> means there are none yet.</td></tr><tr><td><strong>New</strong></td><td>Creates an opportunity in the team pipeline.</td></tr><tr><td><strong>Colour dot</strong></td><td>The team colour. Click it to change the colour.</td></tr></tbody></table><p>Example: the <strong>Sales</strong> team card shows <code>2 Quotations $1,215.00</code>, <code>1 Order to Invoice $1,890.00</code> and <code>Invoiced This Month $0.00 of $25,000.00</code>.</p><p>Click the <strong>Team menu</strong> (three dots) on a card for shortcuts.</p><ul><li><strong>Leads</strong>, <strong>Opportunities</strong>, <strong>Quotations</strong> and <strong>Sales Orders</strong> open that list filtered to the team.</li><li>The four reports, lead analysis, pipeline analysis, forecast and activity analysis, open filtered to the team.</li><li><strong>Configuration</strong> opens the team form.</li><li><strong>Color</strong> changes the card colour.</li></ul><h3 id="list-layout" tabindex="-1">List layout <a class="header-anchor" href="#list-layout" aria-label="Permalink to &quot;List layout&quot;">​</a></h3><p>The list has these columns: <strong>Sales Team</strong> (with the leader underneath), a colour swatch, <strong>Open Opportunities</strong>, <strong>Expected Revenue</strong>, <strong>Members</strong> and <strong>Company</strong>. You can hide <strong>Members</strong> and <strong>Company</strong>. The row action <strong>Pipeline</strong> opens the team pipeline.</p><p>Use the filter to match <strong>Sales Team</strong>, <strong>Team Leader</strong>, <strong>Members</strong>, <strong>Company</strong> and <strong>Created At</strong>. Select rows for bulk actions such as export and delete.</p><h3 id="the-team-pipeline" tabindex="-1">The team pipeline <a class="header-anchor" href="#the-team-pipeline" aria-label="Permalink to &quot;The team pipeline&quot;">​</a></h3><p>Click a team to open <strong>Team name, Pipeline</strong>. It has the Kanban, List and Graph layouts of <a href="./manage-opportunities.html">Manage opportunities</a>, limited to this team. The <strong>Sales Team</strong> field is hidden because it is already set.</p><h2 id="create-a-sales-team" tabindex="-1">Create a sales team <a class="header-anchor" href="#create-a-sales-team" aria-label="Permalink to &quot;Create a sales team&quot;">​</a></h2><p>Example: you set up a team for key accounts.</p><ol><li>Go to <code>CRM → Sales → Teams</code>, or <code>CRM → Configuration → Sales Teams</code>.</li><li>Click <strong>New Sales Team</strong>.</li></ol>',14)),s(a,{src:"/images1/crm/sales-team-create-form.png",alt:"Create Sales Team form filled with the name Key Accounts, a team leader and an invoiced target of 40000 per month"}),e[2]||(e[2]=t('<ol start="3"><li>Fill in the form.</li></ol><h3 id="sales-team" tabindex="-1">Sales Team <a class="header-anchor" href="#sales-team" aria-label="Permalink to &quot;Sales Team&quot;">​</a></h3><ul><li><strong><em>Sales Team:</em></strong> The team name. Required, up to 255 characters.</li></ul><h3 id="team-details" tabindex="-1">Team Details <a class="header-anchor" href="#team-details" aria-label="Permalink to &quot;Team Details&quot;">​</a></h3><ul><li><strong><em>Team Leader:</em></strong> The person who leads the team. Search the users.</li><li><strong><em>Company:</em></strong> The company of the team. The default is the current company. It must be switched on in the top bar. The helper text explains this.</li><li><strong><em>Invoiced Target:</em></strong> The amount the team aims to invoice each month, shown with the suffix <code>/ Month</code>. The default is 0. A value above 0 shows the <strong>Invoiced This Month</strong> line.</li><li><strong><em>Color:</em></strong> A colour that tells teams apart on cards and lists.</li></ul><h3 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h3><ul><li><strong><em>Status:</em></strong> A switch for whether the team is active.</li></ul><p><strong>Example:</strong> Sales Team <code>Key Accounts</code>, Team Leader <code>Sales Admin</code>, Invoiced Target <code>40000</code>, Status on.</p><ol start="4"><li>Click <strong>Create</strong>. You can use <strong>Create &amp; create another</strong> or <strong>Cancel</strong>.</li></ol><p>Members are added on the <strong>Members</strong> tab after the team exists.</p><h2 id="team-tabs" tabindex="-1">Team tabs <a class="header-anchor" href="#team-tabs" aria-label="Permalink to &quot;Team tabs&quot;">​</a></h2><p>After saving, the team has these tabs. A number badge shows the member or rule count.</p><ul><li><strong>View</strong> and <strong>Edit</strong> show and change the form above.</li><li><strong>Assignment Rules</strong> appears when <strong>Automatic Lead Assignment</strong> is on.</li><li><strong>Members</strong> lists the salespeople.</li></ul><p>The team header has <strong>Assign Leads</strong>, <strong>Delete</strong> and <strong>Restore</strong>. <strong>Assign Leads</strong> shows only when automatic assignment is on.</p><h3 id="members" tabindex="-1">Members <a class="header-anchor" href="#members" aria-label="Permalink to &quot;Members&quot;">​</a></h3><p>Each member is a card with the name, email, phone and badges. The badges are <strong>Inactive</strong>, <strong>Skips auto assignment</strong> and the number of rules. With automatic assignment on, the card also shows <strong>Lead limit (30 days)</strong>, for example <code>3 / 30</code>.</p><p>To add a member:</p><ol><li>Open the team and click the <strong>Members</strong> tab.</li><li>Click <strong>Add member</strong>.</li><li>Fill in the form.</li></ol><ul><li><strong><em>Salesperson:</em></strong> The user to add. Required. Each user can be chosen once per team. Use the plus button to create a <strong>New salesperson</strong> with name, email, password, confirm password and roles.</li><li><strong><em>Max leads (30 days):</em></strong> The most leads this person receives in 30 days. Required. The default is 30. Shown when automatic assignment is on.</li><li><strong><em>Pause assignment:</em></strong> Switch on to stop new automatic leads for this person. Shown when automatic assignment is on.</li><li><strong><em>Active:</em></strong> Whether the member is active. The default is on.</li><li><strong>Assignment rules:</strong> Conditions that decide which leads this person gets. Shown when automatic assignment is on.</li></ul><ol start="4"><li>Click <strong>Add member</strong>. A notification <strong>Member added</strong> appears.</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If <strong>Salespeople in Multiple Teams</strong> is off and the user is in another team, a dialog asks to move them. Click <strong>Yes, move</strong>.</p></div><p>Click a member card to edit the name and the fields above. Use <strong>Remove</strong> to take a member out of the team.</p><h3 id="assignment-rules" tabindex="-1">Assignment rules <a class="header-anchor" href="#assignment-rules" aria-label="Permalink to &quot;Assignment rules&quot;">​</a></h3><p>Open the <strong>Assignment Rules</strong> tab. It states which leads the team receives. A line shows the team capacity, such as <code>5 leads assigned this month on a maximum of 60</code>.</p><p>The rules read <strong>Match all of the following rules</strong>. Click <strong>New Rule</strong> to add one. Each row has three parts.</p><ul><li><strong><em>Field:</em></strong> What to test. For example <strong>Country</strong>, <strong>Stage</strong>, <strong>Tags</strong>, <strong>Priority</strong>, <strong>Probability (%)</strong>, <strong>Expected revenue</strong>, <strong>Campaign</strong>, <strong>Medium</strong> or <strong>Source</strong>.</li><li><strong><em>Operator:</em></strong> How to compare. The choices depend on the field.</li><li><strong><em>Value:</em></strong> What to compare with.</li></ul><p>A link under the rules shows how many records match. Click it to list the matching leads and opportunities that are not assigned yet.</p><h3 id="assign-leads" tabindex="-1">Assign Leads <a class="header-anchor" href="#assign-leads" aria-label="Permalink to &quot;Assign Leads&quot;">​</a></h3><p>Click <strong>Assign Leads</strong> in the team header. The dialog lists unassigned leads that match the rules.</p><ol><li>Tick the leads to share out. A line shows the free space of each member.</li><li>Click <strong>Assign</strong>.</li></ol><p>Each lead goes to the member with the most free space. A notification shows how many were assigned and how many were skipped.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Where</th><th>What it does</th></tr></thead><tbody><tr><td><strong>New Sales Team</strong></td><td>Teams page</td><td>Opens the team form.</td></tr><tr><td><strong>Pipeline</strong></td><td>List row</td><td>Opens the team pipeline.</td></tr><tr><td><strong>New</strong></td><td>Grid card</td><td>Creates an opportunity for the team.</td></tr><tr><td><strong>Add member</strong></td><td>Members tab</td><td>Adds a salesperson.</td></tr><tr><td><strong>Assign Leads</strong></td><td>Team header</td><td>Shares unassigned leads among members.</td></tr><tr><td><strong>Delete</strong> and <strong>Restore</strong></td><td>Team header</td><td>Removes a team or brings it back.</td></tr></tbody></table><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li><strong>Open count.</strong> Only deals that are not won and not lost are counted.</li><li><strong>Weekly chart.</strong> It counts opportunities created in each week, including ones later lost.</li><li><strong>Opportunities.</strong> The <strong>Sales Team</strong> field on an opportunity decides which card it counts toward. See <a href="./manage-opportunities.html">Manage opportunities</a>.</li><li><strong>Stages per team.</strong> A stage can be limited to some teams, so a team board shows only its own stages. See <a href="./../configuration/stages.html">Stages</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./manage-opportunities.html">Manage opportunities</a></li><li><a href="./../configuration/settings.html">CRM settings</a></li><li><a href="./../configuration/stages.html">Stages</a></li><li><a href="./../reporting/">CRM reports</a></li></ul>',37))])}const f=o(l,[["render",d]]);export{b as __pageData,f as default};
